<?php namespace App\Notifications; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Notification; use Illuminate\Support\Str; class KomplainSelesaiNotification extends Notification { use Queueable; public $komplain; public function __construct($komplain) { $this->komplain = $komplain; } public function via($notifiable) { return ['database']; } public function toArray($notifiable) { $url = get_class($notifiable) === 'App\Models\Tamu' ? route('guest.riwayat') : route('admin.komplain'); return [ 'type' => 'komplain', 'title' => 'Komplain Selesai Diperbaiki', 'message' => 'Perbaikan untuk "' . Str::limit($this->komplain->deskripsi, 30) . '" telah selesai.', 'url' => $url ]; } }